import sys
CODE = [0, 1, 17, 2, 3, 103, 4, 0, 1, 17, 2, 3, 124, 4, 0, 1, 17, 2, 3, 114, 4, 0, 1, 17, 2, 3, 99, 4, 0, 1, 17, 2, 3, 37, 4, 0, 1, 17, 2, 3, 114, 4, 0, 1, 17, 2, 3, 122, 4, 0, 1, 17, 2, 3, 48, 4, 5]
OPS = {0:'LOAD',1:'PUSH',2:'XOR',3:'CMPEQ',4:'INC',5:'HALT'}
def disasm():
    print('=== disassembly ===')
    i = 0
    while i < len(CODE):
        op = CODE[i]
        if op in (1,3):
            print('%04x: %-6s 0x%02x' % (i, OPS[op], CODE[i+1])); i += 2
        else:
            print('%04x: %s' % (i, OPS[op])); i += 1
def run(inp):
    ptr = 0; i = 0
    while i < len(CODE):
        op = CODE[i]
        if op == 0: st = ord(inp[ptr])
        elif op == 1: a = CODE[i+1]; i += 1; st ^= a
        elif op == 3:
            if st != CODE[i+1]: return False
            i += 1
        elif op == 4: ptr += 1
        elif op == 5: return True
        i += 1
    return False
def solve():
    out = ''; i = 0
    while i < len(CODE):
        if CODE[i] == 3: out += chr(CODE[i+1] ^ 0x11)
        i += 1
    return out
if 'solve' in sys.argv:
    pw = solve()
    print('password =', pw)
    enc = [76, 86, 77, 89, 84, 79, 125, 64, 91, 86, 17, 65, 18, 70, 17, 125, 70, 17, 84, 19, 80, 86, 87, 22, 78, 19, 88, 17, 70, 95]
    print('flag =', bytes(b ^ 0x22 for b in enc).decode())
else:
    disasm()
    print('run with: python3 vmcrack.py solve')
